require __DIR__.'/app/bootstrap.php';if(!setting_bool('blog_portal_enabled',true)){http_response_code(404);exit('Blog is disabled.');}blog_sync_scheduled();$slug=trim((string)($_GET['slug']??''));$lang=in_array(($_GET['lang']??'en'),['en','ur'],true)?$_GET['lang']:'en';$post=$slug?blog_post($slug,true):null;$commentMsg=$commentErr=null;
if($post&&$_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();if(trim((string)($_POST['website']??''))!=='')throw new RuntimeException('Comment could not be submitted.');if(!($post['comments_enabled']??0))throw new RuntimeException('Comments are disabled on this article.');$u=current_user();blog_add_comment((int)$post['id'],trim((string)($_POST['author_name']??($u['name']??''))),trim((string)($_POST['author_email']??($u['email']??''))),trim((string)($_POST['comment_text']??'')),$u?(int)$u['id']:null);$commentMsg=setting_bool('blog_comments_moderation',true)?'Comment submitted for moderation.':'Comment published.';}catch(Throwable $e){$commentErr=$e->getMessage();}}
if($post){blog_increment_view((int)$post['id']);$tags=blog_post_tags((int)$post['id']);$comments=blog_comments((int)$post['id'],true);$related=blog_posts(['category_id'=>$post['category_id']],4);$related=array_values(array_filter($related,fn($r)=>(int)$r['id']!==(int)$post['id']));$embed=blog_video_embed_url((string)$post['video_url']);}else{$q=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$tag=trim((string)($_GET['tag']??''));$filters=['q'=>$q,'category_slug'=>$category,'tag_slug'=>$tag,'language'=>$lang];$posts=blog_posts($filters,setting_int('blog_items_per_page',12));$featured=blog_posts(['featured'=>1,'language'=>$lang],4);$cats=blog_categories(true);$tags=blog_tags();$stats=blog_stats();}
?><!doctype html><html lang="<?=$lang?>" dir="<?=$lang==='ur'?'rtl':'ltr'?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($post?($post['meta_title']?:blog_title($post,$lang)):'Blog — '.setting('site_name','ShahkotPK'))?></title><meta name="description" content="<?=e($post?($post['meta_description']?:blog_excerpt($post,$lang)):'Stories, guides and local perspectives from ShahkotPK.')?>"><?php if($post&&!empty($post['canonical_url'])):?><link rel="canonical" href="<?=e($post['canonical_url'])?>"><?php endif;?><link rel="stylesheet" href="/assets/blog-portal-3.3.0.css?v=330"></head><body><header class="blog-public-header"><div class="blog-shell"><a class="blog-brand" href="/"><i>S</i><span><b><?=e(setting('site_name','ShahkotPK'))?></b><small>Blog & Stories</small></span></a><nav><a href="/">Home</a><a href="/news.php">News</a><a href="/blog.php">Blog</a><a href="/city-guide.php">City Guide</a><a href="/businesses.php">Businesses</a></nav><div><a href="/blog.php?lang=en">EN</a><a href="/blog.php?lang=ur">اردو</a></div></div></header>
<?php if($post):?><section class="blog-detail-hero"><div class="blog-shell"><div class="blog-breadcrumb"><a href="/blog.php">Blog</a><span>›</span><a href="/blog.php?category=<?=urlencode((string)$post['category_slug'])?>"><?=e($post['category_name']?:'Article')?></a></div><div class="blog-detail-grid"><article><span class="blog-kicker"><?=e($post['category_name']?:'SHAHKOTPK BLOG')?></span><h1><?=e(blog_title($post,$lang))?></h1><p><?=e(blog_excerpt($post,$lang))?></p><div class="blog-byline"><b><?=e($post['author_name'])?></b><span><?=e(date('d M Y',strtotime((string)($post['published_at']?:$post['created_at']))))?></span><?php if(setting_bool('blog_show_views',true)):?><span><?=e(number_format((int)$post['views']+1))?> views</span><?php endif;?></div></article><aside class="blog-cover"<?php if($post['cover_image']):?> style="background-image:url('<?=e($post['cover_image'])?>')"<?php endif;?>><?php if($post['post_type']==='video'):?><i>▶</i><?php endif;?></aside></div></div></section><section class="blog-section"><div class="blog-shell blog-article-layout"><main class="blog-article"><?php if($embed):?><div class="blog-video"><iframe src="<?=e($embed)?>" title="<?=e(blog_title($post,$lang))?>" allowfullscreen></iframe></div><?php endif;?><div class="blog-article-body"><?=nl2br(e(blog_body($post,$lang)))?></div><?php if($tags):?><div class="blog-tags"><?php foreach($tags as $tag):?><a href="/blog.php?tag=<?=urlencode((string)$tag['slug'])?>">#<?=e($tag['name'])?></a><?php endforeach;?></div><?php endif;?></main><aside class="blog-author-card"><span>AUTHOR</span><h3><?=e($post['author_name'])?></h3><p><?=e($post['city_name']?:setting('default_city','Shahkot'))?> · <?=e($post['category_name']?:'Blog Contributor')?></p><?php if($post['business_name']):?><a href="/business.php?slug=<?=urlencode((string)$post['business_slug'])?>"><?=e($post['business_name'])?> →</a><?php endif;?></aside></div></section><?php if(($post['comments_enabled']??0)&&setting_bool('blog_comments_enabled',true)):?><section class="blog-section blog-muted"><div class="blog-shell blog-comments-layout"><div><h2>Comments</h2><?php foreach($comments as $c):?><article class="blog-comment"><div><b><?=e($c['author_name'])?></b><span><?=e(date('d M Y',strtotime((string)$c['created_at'])))?></span></div><p><?=nl2br(e($c['comment_text']))?></p></article><?php endforeach;?><?php if(!$comments):?><div class="blog-empty">No approved comments yet.</div><?php endif;?></div><aside class="blog-comment-form"><h3>Join the discussion</h3><?php if($commentMsg):?><div class="blog-success"><?=e($commentMsg)?></div><?php endif;?><?php if($commentErr):?><div class="blog-error"><?=e($commentErr)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="text" name="website" value="" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px;width:1px;height:1px;opacity:0"><input name="author_name" placeholder="Your name" required><input type="email" name="author_email" placeholder="Email (not public)"><textarea name="comment_text" rows="5" placeholder="Write a useful comment..." required></textarea><button>Submit Comment</button></form></aside></div></section><?php endif;?><?php if($related):?><section class="blog-section"><div class="blog-shell"><div class="blog-title-row"><div><span>RELATED</span><h2>More Articles</h2></div></div><div class="blog-grid"><?php foreach(array_slice($related,0,3) as $r):?><article><a class="media" href="/blog.php?slug=<?=urlencode((string)$r['slug'])?>"<?php if($r['cover_image']):?> style="background-image:url('<?=e($r['cover_image'])?>')"<?php endif;?>></a><div><small><?=e($r['category_name']?:'Article')?></small><h3><?=e(blog_title($r,$lang))?></h3><a href="/blog.php?slug=<?=urlencode((string)$r['slug'])?>">Read Article →</a></div></article><?php endforeach;?></div></div></section><?php endif;?>
<?php else:?><section class="blog-hero"><div class="blog-shell blog-hero-grid"><article><span class="blog-kicker">SHAHKOTPK BLOG & STORIES</span><h1>Useful local stories, business insights and city guides written by real contributors.</h1><p>Explore articles from ShahkotPK bloggers and editors covering city life, business, education, lifestyle and technology.</p><div class="blog-hero-actions"><a href="#articles">Explore Articles</a><a href="/login.php">Contributor Login</a></div><div class="blog-category-pills"><?php foreach($cats as $c):?><a href="/blog.php?category=<?=urlencode((string)$c['slug'])?>"><?=e($c['name'])?></a><?php endforeach;?></div></article><aside class="blog-stats"><div><b><?=e($stats['published_count']??0)?></b><span>Published</span></div><div><b><?=e($stats['authors_count']??0)?></b><span>Authors</span></div><div><b><?=e(number_format((int)($stats['total_views']??0)))?></b><span>Views</span></div><div><b><?=e($stats['featured_count']??0)?></b><span>Featured</span></div></aside></div></section><?php if($featured):?><section class="blog-section"><div class="blog-shell"><div class="blog-title-row"><div><span>FEATURED</span><h2>Editor’s Picks</h2></div></div><div class="blog-featured"><?php $lead=array_shift($featured);?><article class="lead"><a class="media" href="/blog.php?slug=<?=urlencode((string)$lead['slug'])?>"<?php if($lead['cover_image']):?> style="background-image:url('<?=e($lead['cover_image'])?>')"<?php endif;?>></a><div><small><?=e($lead['category_name']?:'Featured')?></small><h2><?=e(blog_title($lead,$lang))?></h2><p><?=e(blog_excerpt($lead,$lang))?></p><span>By <?=e($lead['author_name'])?></span><a href="/blog.php?slug=<?=urlencode((string)$lead['slug'])?>">Read Full Article →</a></div></article><div class="side"><?php foreach($featured as $r):?><a href="/blog.php?slug=<?=urlencode((string)$r['slug'])?>"><div class="thumb"<?php if($r['cover_image']):?> style="background-image:url('<?=e($r['cover_image'])?>')"<?php endif;?>></div><span><small><?=e($r['category_name']?:'Blog')?></small><b><?=e(blog_title($r,$lang))?></b><em><?=e($r['author_name'])?></em></span></a><?php endforeach;?></div></div></div></section><?php endif;?><section id="articles" class="blog-section blog-muted"><div class="blog-shell"><div class="blog-title-row"><div><span>LATEST WRITING</span><h2>Latest Articles</h2></div><form class="blog-search"><input type="hidden" name="lang" value="<?=$lang?>"><input name="q" value="<?=e($q)?>" placeholder="Search articles..."><select name="category"><option value="">All Categories</option><?php foreach($cats as $c):?><option value="<?=e($c['slug'])?>" <?=$category===$c['slug']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button>Search</button></form></div><div class="blog-grid"><?php foreach($posts as $r):?><article><a class="media" href="/blog.php?slug=<?=urlencode((string)$r['slug'])?>"<?php if($r['cover_image']):?> style="background-image:url('<?=e($r['cover_image'])?>')"<?php endif;?>><?php if($r['post_type']==='video'):?><i>▶</i><?php endif;?></a><div><div class="meta"><small><?=e($r['category_name']?:'Article')?></small><em><?=e(date('d M Y',strtotime((string)($r['published_at']?:$r['created_at']))))?></em></div><h3><?=e(blog_title($r,$lang))?></h3><p><?=e(blog_excerpt($r,$lang))?></p><span>By <?=e($r['author_name'])?></span><a href="/blog.php?slug=<?=urlencode((string)$r['slug'])?>">Read Article →</a></div></article><?php endforeach;?></div><?php if(!$posts):?><div class="blog-empty"><b>No articles match these filters yet.</b><span>Try another category or return later.</span></div><?php endif;?></div></section><?php endif;?><footer class="blog-footer"><div class="blog-shell"><div><b><?=e(setting('site_name','ShahkotPK'))?> Blog</b><span>Local stories, useful knowledge and community perspectives.</span></div><nav><a href="/">Home</a><a href="/news.php">News</a><a href="/city-guide.php">City Guide</a></nav><small>© <?=date('Y')?> <?=e(setting('site_name','Sha